@ExceptT.exceptT_eq_equivalence
     : forall (Err : Type) (T : Type -> Type) (MT : Monad.Monad T) (QT : Monad.Eq1 T),
       @Monad.Eq1Equivalence T MT QT ->
       @Monad.Eq1Equivalence (EitherMonad.eitherT Err T) (@EitherMonad.Monad_eitherT Err T MT)
         (@ExceptT.exceptT_eq1 Err T QT)

@ExceptT.exceptT_monad_laws
     : forall (Err : Type) (T : Type -> Type) (MT : Monad.Monad T) (QT : Monad.Eq1 T),
       @Monad.Eq1Equivalence T MT QT ->
       @Monad.MonadLawsE T QT MT ->
       @Monad.MonadLawsE (EitherMonad.eitherT Err T) (@ExceptT.exceptT_eq1 Err T QT)
         (@EitherMonad.Monad_eitherT Err T MT)

@ExceptT.exceptT_iteration_uniform
     : forall (Err : Type) (T : Type -> Type) (MT : Monad.Monad T) (QT : Monad.Eq1 T),
       @Monad.Eq1Equivalence T MT QT ->
       @Monad.MonadLawsE T QT MT ->
       forall IT : Basics.MonadIter T,
       @IterationLaws.iteration_uniform T MT IT QT ->
       @IterationLaws.iteration_uniform (EitherMonad.eitherT Err T)
         (@EitherMonad.Monad_eitherT Err T MT) (@Basics.MonadIter_eitherT T Err MT IT)
         (@ExceptT.exceptT_eq1 Err T QT)

@ExceptionFold.exception_effect_throw
     : forall (Err : Type) (E T : Type -> Type) (MT : Monad.Monad T)
         (handle : forall X : Type, E X -> T X) (err : Err),
       @EitherMonad.unEitherT Err T Empty_set
         (@ExceptionFold.exception_effect Err E T MT handle Empty_set
            (@Sum.inl1 (Exception.exceptE Err) E Empty_set (@Exception.Throw Err err))) =
       @Monad.ret T MT (Err + Empty_set) (@inl Err Empty_set err)

@ExceptionFold.exception_effect_forward
     : forall (Err : Type) (E T : Type -> Type) (MT : Monad.Monad T)
         (handle : forall X : Type, E X -> T X) (X : Type) (e : E X),
       @EitherMonad.unEitherT Err T X
         (@ExceptionFold.exception_effect Err E T MT handle X
            (@Sum.inr1 (Exception.exceptE Err) E X e)) =
       @Monad.bind T MT X (Err + X) (handle X e)
         (fun x : X => @Monad.ret T MT (Err + X) (@inr Err X x))

@ExceptionFold.exception_sample_success
     : forall (Err : Type) (MN T : Type -> Type) (MT : Monad.Monad T)
         (sample : forall X : Type, MN X -> T X) (X : Type) (mu : MN X),
       @EitherMonad.unEitherT Err T X (@ExceptionFold.exception_sample Err MN T MT sample X mu) =
       @Monad.bind T MT X (Err + X) (sample X mu)
         (fun x : X => @Monad.ret T MT (Err + X) (@inr Err X x))

@ExceptionFoldFacts.fold_exception_as_iter
     : forall (Err : Type) (E MN T : Type -> Type) (MT : Monad.Monad T)
         (IT : Basics.MonadIter T) (handle : forall X : Type, E X -> T X)
         (sample : forall X : Type, MN X -> T X) (A : Type)
         (t : PTreeDefinition.ptree (Sum.sum1 (Exception.exceptE Err) E) MN A),
       @ExceptionFold.fold_exception Err E MN T MT IT handle sample A t =
       @Basics.iter T IT (Err + A)
         (PTreeDefinition.ptree (Sum.sum1 (Exception.exceptE Err) E) MN A)
         (@ExceptionFoldFacts.exception_fold_step Err E MN T MT handle sample A) t

@ExceptionFoldFacts.fold_run_exception
     : forall (Err : Type) (E MN T : Type -> Type) (MT : Monad.Monad T)
         (IT : Basics.MonadIter T) (QT : Monad.Eq1 T),
       @Monad.Eq1Equivalence T MT QT ->
       @Monad.MonadLawsE T QT MT ->
       forall (handle : forall X : Type, E X -> T X) (sample : forall X : Type, MN X -> T X),
       @IterationLaws.iteration_uniform T MT IT QT ->
       forall (A : Type) (t : PTreeDefinition.ptree (Sum.sum1 (Exception.exceptE Err) E) MN A),
       @Monad.eq1 T QT (Err + A) (@ExceptionFold.fold_exception Err E MN T MT IT handle sample A t)
         (@Fold.fold E MN T MT IT handle sample (Err + A) (@Exception.run_exception Err E MN A t))

@ExceptionFold.exception_target_monad
     : forall (Err : Type) (F : Type -> Type),
       @Monad.MonadLawsE (EitherMonad.eitherT Err (ITreeDefinition.itree F))
         (@ExceptT.exceptT_eq1 Err (ITreeDefinition.itree F) (@ITreeMonad.Eq1_ITree F))
         (@EitherMonad.Monad_eitherT Err (ITreeDefinition.itree F) (@ITreeDefinition.Monad_itree F))
